lete this rate?">Delete</flux:button></td></tr>@empty<tr><td colspan="5" class="py-6 text-zinc-500">No rates configured.</td></tr>@endforelse</tbody></table></div><flux:button size="sm" class="mt-5" wire:click="openRateModal({{ $zone->id }})">Add rate</flux:button></section>@empty<div class="rounded-2xl bg-white p-10 text-center text-sm text-zinc-500 ring-1 ring-zinc-200">No shipping zones configured.</div>@endforelse</div>
    <section class="rounded-2xl bg-white p-6 shadow-sm ring-1 ring-zinc-200"><flux:heading size="lg">Test shipping address</flux:heading><flux:text class="mt-2" variant="subtle">Enter an address to see which zone and rates match.</flux:text><form wire:submit="testShippingAddress" class="mt-5 grid gap-4 sm:grid-cols-2"><flux:select wire:model="testAddress.country_code" label="Country">@foreach ($countries as $code => $country)<option value="{{ $code }}">{{ $country }} ({{ $code }})</option>@endforeach</flux:select><flux:input wire:model="testAddress.province_code" label="State / region" /><flux:input wire:model="testAddress.city" label="City" /><flux:input wire:model="testAddress.postal_code" label="ZIP / postal code" /><div class="sm:col-span-2"><flux:button type="submit">Test address</flux:button></div></form>@if ($testResult)<div class="mt-5 rounded-xl {{ $testResult['zone'] ? 'bg-emerald-50 text-emerald-800' : 'bg-amber-50 text-amber-800' }} p-4 text-sm">@if ($testResult['zone'])<p class="font-medium">Matched zone: {{ $testResult['zone'] }}</p><ul class="mt-2 space-y-1">@foreach ($testResult['rates'] as $rate)<li>{{ $rate['name'] }} — {{ $rate['currency'] }} {{ number_format($rate['price_amount'] / 100, 2) }}</li>@endforeach</ul>@else No shipping zone matches this address.@endif</div>@endif</section>
