    <flux:modal name="rate-form" class="max-w-md" wire:model="showRateModal"><form wire:submit="saveRate" class="space-y-6"><flux:heading size="lg">{{ $editingRate ? 'Edit shipping rate' : 'Add shipping rate' }}</flux:heading><flux:input wire:model="rateName" label="Rate name" placeholder="Standard, Express…" required /><flux:select wire:model.live="rateType" label="Rate type"><option value="flat">Flat rate</option><option value="weight">Weight-based</option><option value="price">Price-based</option><option value="carrier">Carrier-calculated</option></flux:select>@if ($rateType === 'carrier')<flux:callout variant="warning" icon="information-circle">Carrier-calculated rates require a carrier integration.</flux:callout>@else<flux:input wire:model="rateConfig.price" label="Price in cents" type="number" min="0" required />@if (in_array($rateType, ['weight', 'price'], true))<div class="grid gap-4 sm:grid-cols-2"><flux:input wire:model="rateConfig.min" label="{{ $rateType === 'weight' ? 'Min weight (g)' : 'Min order (cents)' }}" type="number" min="0" /><flux:input wire:model="rateConfig.max" label="{{ $rateType === 'weight' ? 'Max weight (g)' : 'Max order (cents)' }}" type="number" min="0" /></div>@endif @endif<label class="flex items-center gap-2 text-sm"><input type="checkbox" wire:model="rateActive" class="rounded border-zinc-300 text-blue-600">Active</label><div class="flex justify-end gap-3"><flux:button type="button" variant="ghost" wire:click="$set('showRateModal', false)">Cancel</flux:button><flux:button type="submit" variant="primary">Save rate</flux:button></div></form></flux:modal>
